query:
    query GetTournamentWithEpisodes($tournamentId: String!) {
  tournament(tournamentId: $tournamentId) {
    uuid
    name
    eventNo
    tournamentStatus
    noOfBullets
    isSatellite
    flight
    noOfEntries
    games {
      uuid
      participants {
        uuid
      }
    }
    visibleSections {
      showSeatingChart
      showChipCount
      showPayouts
      showStructure
      showLiveStream
    }
    days {
      uuid
      name
    }
    payouts {
      participant {
        uuid
        user {
          uuid
          nickname
          countryCode
          photo {
            uuid
            cdnPath
          }
        }
      }
      currency
      uuid
      position
      winAmount
      bountyAmount
    }
    winnerPhoto {
      uuid
      cdnPath
    }
    episodes {
      episodeId
      videoUrl
      dayId
      videoLengthInMs
      title
      description
      published
      episodeNo
      poster {
        uuid
        cdnPath
      }
    }
    festival {
      uuid
      type
      currency
      activeTournamentId
      activeGameId
      liveStreamUrl
      liveStreamTwitchLiveId
      liveStreamYoutubeLiveId
      liveStreamEnabled
    }
  }
}
